mapper.select:
select bp.last_visit_date lastVisitDate, bp.name, bp.mobile, case when btp.treat_type = 0 then '初诊' when btp.treat_type = 1 then '复诊' end as treatType, be.employee_name employeeName from base_patient bp join base_treatment_process btp on btp.patient_id = bp.patient_id join base_employee be on be.user_id = bp.last_visit_doctors
AND bp.org_id = #{form.orgId}
and DATE_FORMAT(bp.last_visit_date, "%Y-%m-%d") > DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(bp.last_visit_date, "%Y-%m-%d") <= DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
AND bp.last_visit_doctors in
#{attendingDoctor}
AND bp.patient_id in
#{ids}
AND btp.treat_type in
#{treatType}
group by bp.last_visit_date desc

select count(bp.origin_type)
from base_patient bp


    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(patient_crt_time) =#{form.year}

select
  bp.origin_type originType,
  bp.origin_type_name originTypeName,
  count(bp.origin_type) countType,
  concat( format(count(bp.origin_type) / ${countOriginType} * 100, 2 ),'%') percentage
from base_patient bp


    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) = #{form.year}


group by  bp.origin_type

select count(bp.gender)
from base_patient bp


    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}

 select
  case when bp.gender = 0 then '男'
       when bp.gender = 1 then '女'
  end gender,
  count(bp.gender) countGender,
  concat( format(count(bp.gender) / ${countGender} * 100, 2 ),'%') percentage
from base_patient bp


    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}


group by bp.gender

select count(1) from base_patient bp


    AND bp.org_id = #{form.orgId}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}

select count(1) from base_patient bp


    AND bp.org_id = #{form.orgId}



    AND ( DATE_FORMAT(now(),'%Y-%m') - DATE_FORMAT(bp.birthday,'%Y-%m') ) <= #{ageOne}



     AND ( DATE_FORMAT(now(),'%Y-%m') - DATE_FORMAT(bp.birthday,'%Y-%m') ) > #{ageTwo}



    AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



    AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



    AND year(bp.patient_crt_time) =#{form.year}
